    "scripture_zh": "但一切永獻的，就是人從他所有永獻給耶和華的，無論是人，是牲畜，是他承受為業的地，都不可賣，也不可贖。凡永獻的是歸給耶和華為至聖。",
    "scripture_en": "'Nevertheless, anything which a man sets apart to the LORD out of all that he has, of man or animal or of the fields of his own property, shall not be sold or redeemed. Anything devoted to destruction is most holy to the LORD.",
    "scripture_he": "כח אַךְ-כָּל-חֵרֶם אֲשֶׁר יַחֲרִם אִישׁ לַיהוָה מִכָּל-אֲשֶׁר-לוֹ, מֵאָדָם וּבְהֵמָה וּמִשְּׂדֵה אֲחֻזָּתוֹ--לֹא יִמָּכֵר, וְלֹא יִגָּאֵל: כָּל-חֵרֶם, קֹדֶשׁ-קָדָשִׁים הוּא לַיהוָה."
