    "chinuch": 480,
    "scripture_zh": "你要謹慎，不可心裡起惡念，說：第七年的豁免年快到了，你便惡眼看你窮乏的弟兄，甚麼都不給他，以致他因你求告耶和華，罪便歸於你了。",
    "scripture_en": "Beware that there is no base thought in your heart, saying, 'The seventh year, the year of remission, is near,' and your eye is hostile toward your poor brother, and you give him nothing; then he may cry to the LORD against you, and it will be a sin in you.",
    "scripture_he": "ט הִשָּׁמֶר לְךָ פֶּן-יִהְיֶה דָבָר עִם-לְבָבְךָ בְלִיַּעַל לֵאמֹר, קָרְבָה שְׁנַת-הַשֶּׁבַע שְׁנַת הַשְּׁמִטָּה, וְרָעָה עֵינְךָ בְּאָחִיךָ הָאֶבְיוֹן, וְלֹא תִתֵּן לוֹ; וְקָרָא עָלֶיךָ אֶל-יְהוָה, וְהָיָה בְךָ חֵטְא."
