    "scripture_en": "Now on the eighth day he is to take two male lambs without defect, and a yearling ewe lamb without defect, and three-tenths of an ephah of fine flour mixed with oil for a grain offering, and one log of oil;",
    "scripture_he": "י וּבַיּוֹם הַשְּׁמִינִי, יִקַּח שְׁנֵי-כְבָשִׂים תְּמִימִם, וְכַבְשָׂה אַחַת בַּת-שְׁנָתָהּ, תְּמִימָה; וּשְׁלֹשָׁה עֶשְׂרֹנִים, סֹלֶת מִנְחָה בְּלוּלָה בַשֶּׁמֶן, וְלֹג אֶחָד, שָׁמֶן."
