    "parashah_zh": "律例篇",
    "chinuch": 397,
    "scripture_zh": "耶和華命定律法中的一條律例乃是這樣說：你要吩咐以色列人，把一隻沒有殘疾、未曾負軛、純紅的母牛牽到你這裡來，",
    "scripture_en": "This is the statute of the law which the LORD has commanded, saying, 'Speak to the sons of Israel that they bring you an unblemished red heifer in which is no defect and on which a yoke has never been placed.",
    "scripture_he": "ב זֹאת חֻקַּת הַתּוֹרָה, אֲשֶׁר-צִוָּה יְהוָה לֵאמֹר: דַּבֵּר אֶל-בְּנֵי יִשְׂרָאֵל, וְיִקְחוּ אֵלֶיךָ פָרָה אֲדֻמָּה תְּמִימָה אֲשֶׁר אֵין-בָּהּ מוּם, אֲשֶׁר לֹא-עָלָה עָלֶיהָ, עֹל."
